sys_script_include.script:
var FleetBlackoutUtils = Class.create();

/**
 * FLEET-18 / FLEET-30: first blackout overlapping the range (start < blackout.end AND end > blackout.start)
 * that applies to the depot (affected_depots empty = all depots). Touching boundaries do not overlap.
 * @returns {GlideRecord|null}
 */
FleetBlackoutUtils.findOverlap = function(startGdt, endGdt, depotSysId) {
    if (!startGdt || !endGdt) {
        return null;
    }
    var start = new GlideDateTime(startGdt);
    var end = new GlideDateTime(endGdt);
    var blk = new GlideRecord('x_1850693_enterp_0_blackout');
    blk.addQuery('start_datetime', '<', end.getValue());
    blk.addQuery('end_datetime', '>', start.getValue());
    if (depotSysId) {
        blk.addEncodedQuery('affected_depotsISEMPTY^ORaffected_depotsLIKE' + depotSysId);
    }
    blk.orderBy('start_datetime');
    blk.setLimit(1);
    blk.query();
    return blk.next() ? blk : null;
};

/** @returns {boolean} true if any blackout overlaps the range for the depot */
FleetBlackoutUtils.overlaps = function(startGdt, endGdt, depotSysId) {
    return FleetBlackoutUtils.findOverlap(startGdt, endGdt, depotSysId) !== null;
};

FleetBlackoutUtils.prototype = {
    initialize: function() {},
    type: 'FleetBlackoutUtils'
};
